// Verificación de la firma HMAC-SHA256.
// El secreto se toma de la variable de entorno de n8n: nunca escribirlo aquí.
const crypto = require('crypto');

const SECRET = $env.DISTRIBUIDORA_WEBHOOK_SECRET;
const TOLERANCE_SECONDS = 300;

if (!SECRET) {
  throw new Error('Falta la variable de entorno DISTRIBUIDORA_WEBHOOK_SECRET');
}

const headers = $input.item.json.headers;
const rawBody = $input.item.json.body;
const timestamp = headers['x-webhook-timestamp'];
const received = headers['x-signature-256'];
const eventId = headers['x-event-id'];

if (!timestamp || !received) {
  throw new Error('Faltan las cabeceras de firma');
}

// El timestamp va firmado: una petición capturada no se puede reenviar después.
const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!Number.isFinite(age) || age > TOLERANCE_SECONDS) {
  throw new Error(`Petición fuera de tolerancia (${age}s)`);
}

const expected = 'sha256=' + crypto
  .createHmac('sha256', SECRET)
  .update(`${timestamp}.${rawBody}`, 'utf8')
  .digest('hex');

// Comparación en tiempo constante.
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(String(received), 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Firma inválida');
}

const payload = JSON.parse(rawBody);
return { json: { ...payload, _event_id: eventId } };

// Descarte de duplicados.
// La entrega es "al menos una vez": si n8n procesa un evento pero la
// respuesta se pierde, el sistema lo reintentará. Sin este paso, un cliente
// podría recibir el mismo recordatorio dos veces.
//
// Esta versión usa la memoria del workflow, que se pierde al reiniciar n8n.
// Para producción, sustituir por una consulta a una tabla o a Redis.
const id = String($input.item.json._event_id ?? $input.item.json.id);
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

if (store.seen[id]) {
  return { json: { ...$input.item.json, _duplicado: true } };
}

store.seen[id] = Date.now();

// Poda: conservar solo los últimos 5000 identificadores.
const ids = Object.keys(store.seen);
if (ids.length > 5000) {
  ids.sort((x, y) => store.seen[x] - store.seen[y])
     .slice(0, ids.length - 5000)
     .forEach((k) => delete store.seen[k]);
}

return { json: { ...$input.item.json, _duplicado: false } };

// PRIMERA AUTOMATIZACIÓN: mensaje de confirmación de pago.
// Aquí solo se arma el texto. Conecta después el nodo de tu canal real
// (WhatsApp Business, Twilio, correo, Telegram).
const d = $input.item.json.data;
const q = (v) => 'Q' + Number(v).toLocaleString('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const saldo = Number(d.remaining_balance);
const cierre = saldo > 0
  ? `Su saldo pendiente es de ${q(saldo)}.`
  : '¡Con este pago su cuenta queda saldada! Gracias por su preferencia.';

const mensaje = [
  `Hola ${d.customer.full_name},`,
  '',
  `Recibimos su pago de ${q(d.amount)} el ${d.payment_date}.`,
  `Recibo: ${d.receipt_number}  ·  Venta: ${d.sale_number}`,
  cierre,
  '',
  'Distribuidora de Electrodomésticos',
].join('\n');

return { json: { telefono: d.customer.phone, mensaje, evento: 'payment.created' } };

// Recordatorio de cuota próxima a vencer.
const d = $input.item.json.data;
const q = (v) => 'Q' + Number(v).toLocaleString('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const mensaje = [
  `Hola ${d.customer.full_name},`,
  '',
  `Le recordamos que su cuota ${d.installment_number} de ${d.installments_count}`,
  `por ${q(d.balance)} vence el ${d.due_date} (en ${d.days_to_due} días).`,
  `Venta: ${d.sale_number}`,
  '',
  'Distribuidora de Electrodomésticos',
].join('\n');

return { json: { telefono: d.customer.phone, mensaje, evento: 'installment.upcoming' } };

// Aviso de cuota vencida.
const d = $input.item.json.data;
const q = (v) => 'Q' + Number(v).toLocaleString('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const mensaje = [
  `Hola ${d.customer.full_name},`,
  '',
  `Su cuota ${d.installment_number} de ${d.installments_count} por ${q(d.balance)}`,
  `venció el ${d.due_date} (${d.days_overdue} días de atraso).`,
  `Venta: ${d.sale_number}`,
  '',
  'Puede pasar a cancelarla o comunicarse con nosotros.',
  'Distribuidora de Electrodomésticos',
].join('\n');

return { json: { telefono: d.customer.phone, mensaje, evento: 'installment.overdue', prioridad: 'alta' } };
